-- Objects outside the public schema that production relies on and `supabase db dump` leaves out.
-- Regenerated from production on 2026-10-16. Storage triggers are platform-managed and not repeated here.

-- Signup creates the profile row; without this trigger a new user has none.
drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created after insert on auth.users
  for each row execute function public.handle_new_user();

-- Storage buckets.
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types) values ('avatars', 'avatars', 't', 5242880, '{image/jpeg,image/png,image/webp}'::text[]) on conflict (id) do update set public = excluded.public, file_size_limit = excluded.file_size_limit, allowed_mime_types = excluded.allowed_mime_types;
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types) values ('echo-media', 'echo-media', 't', 52428800, '{image/jpeg,image/png,image/webp,video/mp4,video/quicktime}'::text[]) on conflict (id) do update set public = excluded.public, file_size_limit = excluded.file_size_limit, allowed_mime_types = excluded.allowed_mime_types;
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types) values ('marketplace-photos', 'marketplace-photos', 't', 10485760, '{image/jpeg,image/png,image/webp,image/heic,image/heif}'::text[]) on conflict (id) do update set public = excluded.public, file_size_limit = excluded.file_size_limit, allowed_mime_types = excluded.allowed_mime_types;
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types) values ('dm-media', 'dm-media', 'f', 52428800, '{image/jpeg,image/png,image/webp,image/heic,image/heif,video/mp4,video/quicktime,video/x-m4v,video/webm}'::text[]) on conflict (id) do update set public = excluded.public, file_size_limit = excluded.file_size_limit, allowed_mime_types = excluded.allowed_mime_types;
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types) values ('mini-app-media', 'mini-app-media', 'f', 52428800, '{image/jpeg,image/png,image/webp,image/heic,image/heif,video/mp4,video/quicktime,video/x-m4v,video/webm,audio/mp4,audio/mpeg,audio/wav}'::text[]) on conflict (id) do update set public = excluded.public, file_size_limit = excluded.file_size_limit, allowed_mime_types = excluded.allowed_mime_types;
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types) values ('verification', 'verification', 'f', 5242880, '{image/jpeg}'::text[]) on conflict (id) do update set public = excluded.public, file_size_limit = excluded.file_size_limit, allowed_mime_types = excluded.allowed_mime_types;

-- Storage policies on storage.objects.
drop policy if exists avatars_authenticated_delete_own_prefix on storage.objects; create policy avatars_authenticated_delete_own_prefix on storage.objects as permissive for delete to authenticated using (((bucket_id = 'avatars'::text) AND ((storage.foldername(name))[1] = (auth.uid())::text)));
drop policy if exists avatars_authenticated_insert_own_prefix on storage.objects; create policy avatars_authenticated_insert_own_prefix on storage.objects as permissive for insert to authenticated  with check (((bucket_id = 'avatars'::text) AND ((storage.foldername(name))[1] = (auth.uid())::text)));
drop policy if exists avatars_authenticated_update_own_prefix on storage.objects; create policy avatars_authenticated_update_own_prefix on storage.objects as permissive for update to authenticated using (((bucket_id = 'avatars'::text) AND ((storage.foldername(name))[1] = (auth.uid())::text))) with check (((bucket_id = 'avatars'::text) AND ((storage.foldername(name))[1] = (auth.uid())::text)));
drop policy if exists avatars_owner_delete on storage.objects; create policy avatars_owner_delete on storage.objects as permissive for delete to public using (((bucket_id = 'avatars'::text) AND ((auth.uid())::text = (storage.foldername(name))[1])));
drop policy if exists avatars_owner_update on storage.objects; create policy avatars_owner_update on storage.objects as permissive for update to public using (((bucket_id = 'avatars'::text) AND ((auth.uid())::text = (storage.foldername(name))[1])));
drop policy if exists avatars_owner_upload on storage.objects; create policy avatars_owner_upload on storage.objects as permissive for insert to public  with check (((bucket_id = 'avatars'::text) AND ((auth.uid())::text = (storage.foldername(name))[1])));
drop policy if exists dm_media_delete on storage.objects; create policy dm_media_delete on storage.objects as permissive for delete to authenticated using (((bucket_id = 'dm-media'::text) AND ((storage.foldername(name))[1] = (auth.uid())::text)));
drop policy if exists dm_media_read on storage.objects; create policy dm_media_read on storage.objects as permissive for select to authenticated using (((bucket_id = 'dm-media'::text) AND (((storage.foldername(name))[1] = (( SELECT auth.uid() AS uid))::text) OR (EXISTS ( SELECT 1
   FROM direct_messages dm
  WHERE (((dm.sender_id)::text = (storage.foldername(objects.name))[1]) AND ((dm.media_url = objects.name) OR ("right"(dm.media_url, (length(objects.name) + 1)) = ('/'::text || objects.name)) OR (dm.voice_url = objects.name) OR ("right"(dm.voice_url, (length(objects.name) + 1)) = ('/'::text || objects.name))) AND is_dm_conversation_member(dm.conversation_id, ( SELECT auth.uid() AS uid))))))));
drop policy if exists dm_media_update on storage.objects; create policy dm_media_update on storage.objects as permissive for update to authenticated using (((bucket_id = 'dm-media'::text) AND ((storage.foldername(name))[1] = (auth.uid())::text))) with check (((bucket_id = 'dm-media'::text) AND ((storage.foldername(name))[1] = (auth.uid())::text)));
drop policy if exists dm_media_upload on storage.objects; create policy dm_media_upload on storage.objects as permissive for insert to authenticated  with check (((bucket_id = 'dm-media'::text) AND ((storage.foldername(name))[1] = (auth.uid())::text)));
drop policy if exists echo_media_owner_delete on storage.objects; create policy echo_media_owner_delete on storage.objects as permissive for delete to public using (((bucket_id = 'echo-media'::text) AND ((auth.uid())::text = (storage.foldername(name))[1])));
drop policy if exists echo_media_owner_upload on storage.objects; create policy echo_media_owner_upload on storage.objects as permissive for insert to public  with check (((bucket_id = 'echo-media'::text) AND ((auth.uid())::text = (storage.foldername(name))[1])));
drop policy if exists echo_media_public_read on storage.objects; create policy echo_media_public_read on storage.objects as permissive for select to public using (((bucket_id = 'echo-media'::text) AND (split_part(name, '/'::text, 1) = (auth.uid())::text)));
drop policy if exists marketplace_photos_authenticated_delete_own_prefix on storage.objects; create policy marketplace_photos_authenticated_delete_own_prefix on storage.objects as permissive for delete to authenticated using (((bucket_id = 'marketplace-photos'::text) AND (split_part(name, '/'::text, 1) = (auth.uid())::text)));
drop policy if exists marketplace_photos_authenticated_insert_own_prefix on storage.objects; create policy marketplace_photos_authenticated_insert_own_prefix on storage.objects as permissive for insert to authenticated  with check (((bucket_id = 'marketplace-photos'::text) AND (split_part(name, '/'::text, 1) = (auth.uid())::text)));
drop policy if exists marketplace_photos_authenticated_update_own_prefix on storage.objects; create policy marketplace_photos_authenticated_update_own_prefix on storage.objects as permissive for update to authenticated using (((bucket_id = 'marketplace-photos'::text) AND (split_part(name, '/'::text, 1) = (auth.uid())::text))) with check (((bucket_id = 'marketplace-photos'::text) AND (split_part(name, '/'::text, 1) = (auth.uid())::text)));
drop policy if exists marketplace_photos_delete on storage.objects; create policy marketplace_photos_delete on storage.objects as permissive for delete to public using (((bucket_id = 'marketplace-photos'::text) AND ((storage.foldername(name))[1] = (auth.uid())::text)));
drop policy if exists marketplace_photos_upload on storage.objects; create policy marketplace_photos_upload on storage.objects as permissive for insert to public  with check (((bucket_id = 'marketplace-photos'::text) AND (auth.role() = 'authenticated'::text) AND ((storage.foldername(name))[1] = (auth.uid())::text)));
drop policy if exists mini_app_media_delete on storage.objects; create policy mini_app_media_delete on storage.objects as permissive for delete to authenticated using (((bucket_id = 'mini-app-media'::text) AND ((storage.foldername(name))[1] = (auth.uid())::text)));
drop policy if exists mini_app_media_read on storage.objects; create policy mini_app_media_read on storage.objects as permissive for select to authenticated using (((bucket_id = 'mini-app-media'::text) AND ((storage.foldername(name))[1] = (auth.uid())::text)));
drop policy if exists mini_app_media_update on storage.objects; create policy mini_app_media_update on storage.objects as permissive for update to authenticated using (((bucket_id = 'mini-app-media'::text) AND ((storage.foldername(name))[1] = (auth.uid())::text))) with check (((bucket_id = 'mini-app-media'::text) AND ((storage.foldername(name))[1] = (auth.uid())::text)));
drop policy if exists mini_app_media_upload on storage.objects; create policy mini_app_media_upload on storage.objects as permissive for insert to authenticated  with check (((bucket_id = 'mini-app-media'::text) AND ((storage.foldername(name))[1] = (auth.uid())::text)));
drop policy if exists "verification selfie read own or moderator" on storage.objects; create policy "verification selfie read own or moderator" on storage.objects as permissive for select to authenticated using (((bucket_id = 'verification'::text) AND ((name ~~ (auth.uid() || '/%'::text)) OR (EXISTS ( SELECT 1
   FROM profiles
  WHERE ((profiles.id = auth.uid()) AND (profiles.is_moderator = true)))))));
drop policy if exists "verification selfie upload own" on storage.objects; create policy "verification selfie upload own" on storage.objects as permissive for insert to authenticated  with check (((bucket_id = 'verification'::text) AND (name ~~ (auth.uid() || '/%'::text))));
